window.HOEREN_TESTS[48] = {"id":"im-theater","name":"Im Theater","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Theater-Besucher: Die Vorstellung ‚Romeo und Julia‘ beginnt heute Abend um 19 Uhr 30, nicht um 19 Uhr und nicht um 20 Uhr. Bitte seid 15 Minuten vorher da, die Garderobe gibt es im Untergeschoss. Während der Vorstellung sind Handys aus, und Fotografieren ist nicht erlaubt. Pause nach dem dritten Akt. Viel Spaß!","gender":"f","q":"Wann beginnt die Vorstellung?","opts":["19 Uhr.","20 Uhr.","19 Uhr 30."],"correct":2},{"transcript":"Hallo Markus, hier ist Anna. Hast du Lust auf Theater am Freitag? Es wird nicht Romeo und Julia und nicht Hamlet gespielt, sondern Faust. Klassik, aber modern inszeniert. Ich habe schon Tickets gekauft, vorne sitzen wir. Treffen um 18 Uhr 30 vor dem Theater. Sag bitte zu oder ab!","gender":"f","q":"Welches Stück?","opts":["Faust.","Romeo und Julia.","Hamlet."],"correct":0},{"transcript":"Achtung Theater-Gäste: Die heutige Vorstellung fängt 15 Minuten später an. Der Hauptdarsteller ist nicht krank und die Technik ist in Ordnung. Er hatte Stau auf der Autobahn und ist gerade angekommen. Wir entschuldigen uns. Die Pause wird länger sein, damit ihr nicht zu spät heimkommt. Danke für eure Geduld!","gender":"m","q":"Warum die Verspätung?","opts":["Schauspieler im Stau.","Probleme mit Technik.","Schauspieler krank."],"correct":0},{"transcript":"Hi Lisa, hier ist Tom. Pass auf, ich kann heute Abend nicht ins Theater kommen. Ich habe Zeit und ich bin selbst nicht krank, aber mein Sohn ist plötzlich krank und hat hohes Fieber. Kannst du die Karte verkaufen oder Anna mitnehmen? Beim nächsten Mal komme ich, versprochen. Tschüs und sorry!","gender":"m","q":"Warum kommt Tom nicht?","opts":["Er hat keine Zeit.","Er ist selbst krank.","Sein Sohn ist krank."],"correct":2},{"transcript":"Liebe Abonnenten: Die neue Theater-Saison startet im September. Hauptstück ist ‚Die Räuber‘ von Schiller, Premiere am 15. September. Karten sind ab heute online buchbar, nicht nur offline. Der Studenten-Rabatt bleibt 50 Prozent wie immer. Der Senioren-Rabatt ist jetzt höher, 30 Prozent statt 25 Prozent. Wir freuen uns auf euch!","gender":"f","q":"Was hat sich geändert?","opts":["Studenten-Rabatt höher.","Senioren-Rabatt höher.","Karten nur offline."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Welche Vorstellung läuft an welchem Tag? Wählen Sie für jeden Tag einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Hast du den Spielplan für diese Woche schon gesehen?"},{"speaker":"Lisa","gender":"f","text":"Fünf Abende sind noch frei. Ich möchte nichts davon verpassen."},{"speaker":"Lukas","gender":"m","text":"Das Kinderstück läuft am Dienstag. Um sechs ist es extra für die Kleinen."},{"speaker":"Lisa","gender":"f","text":"Die Kinder freuen sich schon sehr darauf. Läuft das Musical Cats auch diese Woche?"},{"speaker":"Lukas","gender":"m","text":"Nein. Für das Musical Cats gibt es keine Karten mehr."},{"speaker":"Lisa","gender":"f","text":"Was kommt am nächsten Tag?"},{"speaker":"Lukas","gender":"m","text":"Ballett Schwanensee gibt es am Mittwoch. Die Musik dazu ist besonders schön."},{"speaker":"Lisa","gender":"f","text":"Das wird ruhig und fein. Was gibt es am Donnerstag?"},{"speaker":"Lukas","gender":"m","text":"Das Comedy-Stück kommt dann. Wir lachen dort mit Freunden."},{"speaker":"Lisa","gender":"f","text":"Das passt gut zu uns. Gibt es auch Krimi-Theater?"},{"speaker":"Lukas","gender":"m","text":"Nein. Krimi-Theater spielen sie diese Woche nicht."},{"speaker":"Lisa","gender":"f","text":"Dann möchte ich am Freitag etwas Ernstes sehen."},{"speaker":"Lukas","gender":"m","text":"Sie spielen dann Faust. Das Stück dauert bis spät in die Nacht."},{"speaker":"Lisa","gender":"f","text":"Darauf freue ich mich wirklich. Was bleibt dann für den Samstag übrig?"},{"speaker":"Lukas","gender":"m","text":"Sie spielen dann Romeo und Julia. Ich hole die Karten noch heute."},{"speaker":"Lisa","gender":"f","text":"Wir treffen uns vorher an der Tür."}],"options":[{"letter":"a","text":"Faust"},{"letter":"b","text":"Musical Cats"},{"letter":"c","text":"Kinderstück"},{"letter":"d","text":"Comedy-Stück"},{"letter":"e","text":"Romeo und Julia"},{"letter":"f","text":"Kabarett"},{"letter":"g","text":"Ballett Schwanensee"},{"letter":"h","text":"Oper Don Giovanni"},{"letter":"i","text":"Krimi-Theater"}],"items":[{"person":"Dienstag","correct":"c"},{"person":"Mittwoch","correct":"g"},{"person":"Donnerstag","correct":"d"},{"person":"Freitag","correct":"a"},{"person":"Samstag","correct":"e"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag, ich möchte zwei Karten für ‚Faust‘ bitte, für das Wochenende."},{"speaker":"Verkäuferin","gender":"f","text":"Gerne, für welchen Tag denn, Freitag, Samstag oder Sonntag?"},{"speaker":"Kunde","gender":"m","text":"Am liebsten Samstag um 20 Uhr, da habe ich Zeit."},{"speaker":"Verkäuferin","gender":"f","text":"Samstag ist leider ausverkauft. Freitag ist auch voll. Sonntag um 18 Uhr haben wir noch Plätze."},{"speaker":"Kunde","gender":"m","text":"Dann nehme ich Sonntag. Zwei Karten bitte, danke für die Hilfe!"}],"q":"Welcher Tag?","opts":["Samstag.","Sonntag.","Freitag."],"correct":1},{"lines":[{"speaker":"Besucher","gender":"m","text":"Entschuldigung, wo ist bitte meine Reihe 5, Platz 10? Ich finde den Weg nicht."},{"speaker":"Platzanweiserin","gender":"f","text":"Das ist im Erdgeschoss, sechste Reihe von vorne, in der mittleren Sektion. Keine Treppe nötig."},{"speaker":"Besucher","gender":"m","text":"Also nicht im ersten Stock und nicht in der Galerie? Brauche ich den Aufzug?"},{"speaker":"Platzanweiserin","gender":"f","text":"Nein, Sie bleiben im Erdgeschoss. Gehen Sie einfach geradeaus durch die Tür, dann sehen Sie Ihre Reihe."},{"speaker":"Besucher","gender":"m","text":"Alles klar, Erdgeschoss, Reihe 5. Vielen Dank!"}],"q":"Wo ist sein Platz?","opts":["Im Erdgeschoss.","Im ersten Stock.","In der Galerie."],"correct":0},{"lines":[{"speaker":"Tochter","gender":"f","text":"Papa, wie lang dauert das Stück heute Abend? Ich habe schon Hunger."},{"speaker":"Vater","gender":"m","text":"Drei Stunden mit Pause. Zwei Stunden ist kurz, vier Stunden ist zu lang für dich."},{"speaker":"Tochter","gender":"f","text":"Drei Stunden, so lang? Kann ich in der Pause etwas essen?"},{"speaker":"Vater","gender":"m","text":"Ja, in der Pause gibt es Brötchen. Das Stück ist ein Klassiker, aber spannend."},{"speaker":"Tochter","gender":"f","text":"Okay, dann bleibe ich dabei. In der Pause hole ich uns etwas."}],"q":"Wie lange dauert das Stück?","opts":["Drei Stunden.","Zwei Stunden.","Vier Stunden."],"correct":0},{"lines":[{"speaker":"Sohn","gender":"m","text":"Mama, ich muss dringend aufs Klo. Es geht nicht mehr lange."},{"speaker":"Mutter","gender":"f","text":"Jetzt, während des Stücks? Kannst du nicht sitzen bleiben bis zur Pause?"},{"speaker":"Sohn","gender":"m","text":"Nein, jetzt. Ich kann nicht sitzen bleiben, und allein mit dir gehen will ich auch nicht."},{"speaker":"Mutter","gender":"f","text":"Dann geh leise raus, hinten ist die Tür. Komm danach schnell wieder, ja?"},{"speaker":"Sohn","gender":"m","text":"Okay, ich gehe leise. Bis gleich, Mama!"}],"q":"Was muss der Sohn tun?","opts":["Sitzen bleiben.","Mit der Mutter gehen.","Aufs Klo gehen."],"correct":2},{"lines":[{"speaker":"Frau","gender":"f","text":"Na, wie war das Stück für dich? Mir hat es sehr gefallen."},{"speaker":"Mann","gender":"m","text":"Gut gespielt, aber für mich war es zu lang. Nach zwei Stunden war ich müde."},{"speaker":"Frau","gender":"f","text":"Zu kurz fandest du es also nicht? Ich dachte, die Länge ist genau richtig."},{"speaker":"Mann","gender":"m","text":"Nein, nicht zu kurz und nicht genau richtig. Ich mag Stücke lieber kürzer."},{"speaker":"Frau","gender":"f","text":"Verstehe, dann gehen wir nächstes Mal zu einer Komödie. Die sind oft kürzer."}],"q":"Was sagt der Mann?","opts":["Genau richtig.","Zu kurz.","Zu lang."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Weber, einer Theater-Schauspielerin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Weber, Sie sind seit 20 Jahren Schauspielerin. Wie sind Sie zum Theater gekommen?"},{"speaker":"Weber","gender":"f","text":"In der Schule hatte ich eine Theater-AG, sofort verliebt in die Bühne. Erst wollte ich Lehrerin werden, sicherer Beruf. Aber die Bühne hat mich nie losgelassen. Schauspielschule, dann Anfangs-Jobs in kleinen Theatern — jetzt großes Haus."},{"speaker":"Reporter","gender":"m","text":"Welche Rollen spielen Sie am liebsten?"},{"speaker":"Weber","gender":"f","text":"Komplizierte Frauen — nicht einfache Heldinnen. Lady Macbeth, Medea, solche Rollen. Komödie spiele ich seltener — schwerer als Drama, eigentlich. Komik muss perfekt sein, sonst peinlich."},{"speaker":"Reporter","gender":"m","text":"Wie lange dauert eine Probenphase?"},{"speaker":"Weber","gender":"f","text":"Etwa 6 bis 8 Wochen. Erst Lesen, dann Stellproben, dann Bühnen-Proben mit Kostüm und Technik. Generalprobe am Ende, dann Premiere. Stressige Zeit, aber spannend. Ohne Probe geht nichts."},{"speaker":"Reporter","gender":"m","text":"Was ist das Schwerste am Beruf?"},{"speaker":"Weber","gender":"f","text":"Unregelmäßiges Leben. Abend-Vorstellungen, Wochenende arbeiten, wenig Freizeit. Auch finanziell schwer — manche Theater zahlen schlecht. Kinder haben ist fast unmöglich. Familie leidet."},{"speaker":"Reporter","gender":"m","text":"Was raten Sie jungen Schauspielern?"},{"speaker":"Weber","gender":"f","text":"Realistisch bleiben — nicht jeder wird Star. Plan B haben, anderes lernen. Aber wenn Bühne der Traum ist — kämpfen! Hart arbeiten, ständig lernen, geduldig sein. Anerkennung kommt langsam."}],"items":[{"q":"Sie spielt am liebsten einfache Heldinnen.","correct":"nein"},{"q":"Frau Weber wollte zuerst Lehrerin werden.","correct":"ja"},{"q":"Eine Probenphase dauert etwa 6 bis 8 Wochen.","correct":"ja"},{"q":"Der Beruf passt sehr gut zu Familienleben.","correct":"nein"},{"q":"Sie rät jungen Schauspielern, einen Plan B zu haben.","correct":"ja"}]}]};
